import Foundation
@testable import Blanc

/// Fixtures are generated by desktop's actual modules, not reimplemented test logic.
enum SyncVectors {
    private final class BundleToken: NSObject {}
    enum Failure: Error { case missingFixture, missingSection(String) }

    static func load() throws -> JSONValue {
        let bundle = Bundle(for: BundleToken.self)
        guard let url = bundle.url(forResource: "sync-vectors", withExtension: "json")
            ?? bundle.url(forResource: "sync-vectors", withExtension: "json", subdirectory: "Sync/Fixtures")
            ?? bundle.url(forResource: "sync-vectors", withExtension: "json", subdirectory: "Fixtures") else {
            throw Failure.missingFixture
        }
        return try JSONValue(data: Data(contentsOf: url))
    }

    static func section(_ name: String) throws -> [JSONValue] {
        guard let value = try load()[name], case .array(let entries) = value, !entries.isEmpty else {
            throw Failure.missingSection(name)
        }
        return entries
    }
}
